// THE 80% GAME — SINGLE-FILE RENDER EDITION
// Same multiplayer game, bots and animations as version 1.2.
// Node.js 20+; no dependencies and no external APIs.
// This self-contained launcher extracts bundled source into a temporary directory.
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const zlib = require('node:zlib');
const source = '';
const assets = JSON.parse(zlib.gunzipSync(Buffer.from(source,'base64')).toString('utf8'));
const directory = fs.mkdtempSync(path.join(os.tmpdir(), '80-percent-game-'));
for (const [filename,content] of Object.entries(assets)) {
  if (path.isAbsolute(filename) || filename.split('/').includes('..')) throw new Error('Invalid filename');
  const dest = path.join(directory,filename);
  fs.mkdirSync(path.dirname(dest),{recursive:true});
  fs.writeFileSync(dest,Buffer.from(content,'base64'));
}
const {server} = require(path.join(directory,'server.js'));
const port = Number(process.env.PORT) || 3000;
server.listen(port,'0.0.0.0',()=>console.log(`The 80% Game: http://localhost:${port}`));